# A5 量化中 rmsnorm 无需 bias，但以下 WithBias 模式类仍然存在
# （根据评审意见推断）评审人指出应全部删除

class RMSNormWithBiasQuantFusionPattern(QuantFusionPattern):
    """Pattern for fusing RMSNorm(with bias) + DynamicMxQuant."""

    def __init__(self, eps: float):
        super().__init__()
        self.eps = eps

    def get_input_node(self):
        return Node(ops.rms_norm_with_bias, ...)

    def get_output_node(self):
        return Node(ops.npu_dynamic_mx_quant, ...)


class AddRMSNormWithBiasQuantFusionPattern(QuantFusionPattern):
    """Pattern for fusing AddRMSNorm(with bias) + DynamicMxQuant."""

    def __init__(self, eps: float):
        super().__init__()
        self.eps = eps

    def get_input_node(self):
        return Node(ops.add_rms_norm_with_bias, ...)

    def get_output_node(self):
        return Node(ops.npu_add_rms_norm_dynamic_mx_quant,
                    epsilon=self.epsilion)  # gemini 发现的 typo


class RMSNormQuantFusionPattern(QuantFusionPattern):
    """Pattern for fusing RMSNorm(no bias) + DynamicMxQuant."""

    def __init__(self, eps: float):
        super().__init__()
        self.eps = eps

